/**
 * Dual-layer fallback brand logo resolver for Katulistiwa mobile app.
 * Layer 1: Local bundled asset require('../../assets/logo.png')
 * Layer 2: Embedded Base64 Data-URI fallback when asset bundling fails or throws
 * Rule R-02 compliant: Zero em dashes in code, strings, and comments.
 */

export const FALLBACK_LOGO_URI =
  'data:image/png;base64,';

/**
 * Resolves the logo source depending on error state and runtime environment.
 * @param {boolean} [hasError=false] - Whether previous image load encountered an error.
 * @returns {object|number} Image source object or Metro asset ID.
 */
export function getBrandLogoSource(hasError) {
  if (hasError) {
    return { uri: FALLBACK_LOGO_URI };
  }
  try {
    if (typeof require === 'function') {
      return require('../../assets/logo.png');
    }
  } catch (_err) {
    return { uri: FALLBACK_LOGO_URI };
  }
  return { uri: FALLBACK_LOGO_URI };
}
